def max_non_palindrome_substring(s):
    n = len(s)
    dp = [[False] * n for _ in range(n)]
    max_length = 0

    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if i == j:
                dp[i][j] = True
            elif i + 1 == j:
                dp[i][j] = s[i] != s[j]
            else:
                dp[i][j] = s[i] == s[j] and dp[i + 1][j - 1]

            if dp[i][j]:
                continue

            max_length = max(max_length, j - i + 1)

    return max_length

